-- Preserve published packs; new clients opt in with supportedSchemaVersion=3.
ALTER TABLE missions DROP CONSTRAINT ck_missions_trigger_type;
ALTER TABLE missions ADD CONSTRAINT ck_missions_trigger_type CHECK (trigger_type IN (
    'TURN_SIGNAL_OFF', 'WIPER_ON', 'LOW_BEAM_ON', 'NAVI_NEXT_TURN', 'NEAR_DESTINATION', 'NAVI_TRIP_INFO', 'TRIP_STARTED', 'MISSION_CORRECT', 'TRIP_PAUSED', 'NO_EVENT_TIMEOUT', 'DESTINATION_ARRIVED', 'MISSION_COMPLETED', 'WIPER_OFF', 'SPEED_STABLE', 'VEHICLE_STOPPED', 'TURN_SIGNAL_SUMMARY', 'SPEED_CHANGED', 'TRIP_ENDED'
));

DO $$
DECLARE
    new_pack_id BIGINT;
BEGIN
    IF EXISTS (SELECT 1 FROM mission_packs WHERE code = 'DEFAULT' AND version = 4) THEN
        RAISE EXCEPTION 'DEFAULT version 4 already exists; refusing to overwrite it';
    END IF;

    INSERT INTO mission_packs (code, version, schema_version, status)
    VALUES ('DEFAULT', 4, 3, 'DRAFT') RETURNING id INTO new_pack_id;

    INSERT INTO missions (mission_pack_id, code, trigger_type, config) VALUES
    (new_pack_id, 'BLINK', 'TURN_SIGNAL_OFF', $config$
{"title":"깜빡이 소리","sourceIds":["F-01"],"trigger":{"event":"TURN_SIGNAL_OFF","minOnMs":1000,"directionRequired":true},"execution":{"validity":{"mode":"TIME","durationMs":30000},"cooldownSecondsByIntensity":{"LOW":300,"NORMAL":180,"HIGH":120},"holdWhen":{"turnSignalOn":true,"naviSpeaking":true},"askWhen":"DRIVING","noAnswerCompletes":false,"presentationOnly":false},"ageContent":{"AGE_5_6":{"question":"똑딱똑딱! 이 소리 들렸어요?","answerKind":"YES_NO","expectedAnswer":"YES","correctMessage":"정확해요! 기장님이 깜빡이를 켰어요.","wrongMessage":"앗, 기장님이 켰어요. 다음엔 더 잘 들어봐요!"},"AGE_7_8":{"question":"방금 똑딱 소리가 났어요. 기장님이 깜빡이를 켰나요?","answerKind":"YES_NO","expectedAnswer":"YES","correctMessage":"정확해요! 기장님이 깜빡이를 켰어요.","wrongMessage":"앗, 기장님이 켰어요. 다음엔 더 잘 들어봐요!"},"AGE_9_PLUS":{"question":"방금 깜빡이는 왼쪽이었을까, 오른쪽이었을까?","answerKind":"LEFT_RIGHT","expectedAnswer":"TURN_SIGNAL_DIRECTION","correctMessage":"정확해요! 기장님이 깜빡이를 켰어요.","wrongMessage":"정답은 {side}이었어요!"}}}$config$::jsonb),

